/** Independent generated bytes, never a file read or recording claim. */
import { createHash } from 'node:crypto';
export const nodeDigest = async (algorithm: 'SHA-256'|'SHA-512', bytes: Uint8Array) => createHash(algorithm === 'SHA-256' ? 'sha256' : 'sha512').update(bytes).digest('hex');
export function pair(count = 1024, sha512 = false) {
  const data = new Uint8Array(count * 4);
  const view = new DataView(data.buffer);
  for (let i=0;i<count;i++) { view.setInt16(i*4, Math.round(8192*Math.cos(2*Math.PI*16*i/1024)),true); view.setInt16(i*4+2,Math.round(8192*Math.sin(2*Math.PI*16*i/1024)),true); }
  const global: Record<string,unknown> = {'core:datatype':'ci16_le','core:version':'1.2.6','core:sample_rate':1024};
  if (sha512) global['core:sha512'] = createHash('sha512').update(data).digest('hex');
  const metadata = new TextEncoder().encode(' \n'+JSON.stringify({global,captures:[{'core:sample_start':0,'core:frequency':1000000}],annotations:[]})+'\t\n');
  return {metadata,data};
}
export function deferred<T>() { let resolve!: (value:T)=>void; let reject!: (reason:unknown)=>void; const promise=new Promise<T>((yes,no)=>{resolve=yes;reject=no;}); return {promise,resolve,reject}; }
